"""CurvTab Dental 2.0 — Phase 3 Reception Checkout installer.

Run from the Codespaces repository root:
    python3 curvtab_phase3_checkout.py

Only adds files and patches App.tsx/DentalDbContext.cs. It neither runs
migrations nor resets a database, and refuses to overwrite existing files.
"""
from pathlib import Path
from datetime import datetime, timezone
import shutil
import sys

ROOT = Path.cwd()
APP = ROOT / 'frontend/src/App.tsx'
DB = ROOT / 'backend/CurvTabDental.Infrastructure/Persistence/DentalDbContext.cs'
CLINICAL = ROOT / 'backend/CurvTabDental.API/Controllers/ConsultationsController.cs'
FRONTDESK = ROOT / 'backend/CurvTabDental.API/Controllers/FrontDeskCheckoutController.cs'

for file in (APP, DB, CLINICAL, FRONTDESK):
    if not file.is_file():
        sys.exit(f'ERROR: Required existing file not found: {file}\nNo files changed.')

FILE_PAYMENT = 'using CurvTabDental.Domain.Common;\n\nnamespace CurvTabDental.Domain.Entities;\n\n// Immutable receipt-backed record of money actually received.\n// Card numbers and security codes must NEVER be stored here.\npublic sealed class Payment : IPracticeOwned\n{\n    public Guid Id { get; set; } = Guid.NewGuid();\n    public Guid DentalPracticeId { get; set; }\n    public Guid AppointmentId { get; set; }\n    public Guid RequestId { get; set; }\n    public string ReceiptNumber { get; set; } = string.Empty;\n    public decimal Amount { get; set; }\n    public string Method { get; set; } = string.Empty;\n    public string? Reference { get; set; }\n    public DateTime ReceivedAtUtc { get; set; } = DateTime.UtcNow;\n    public Guid ReceivedByUserId { get; set; }\n}\n'

FILE_CONTROLLER = 'using CurvTabDental.Application.Abstractions;\nusing CurvTabDental.Domain.Entities;\nusing CurvTabDental.Infrastructure.Persistence;\nusing Microsoft.AspNetCore.Authorization;\nusing Microsoft.AspNetCore.Mvc;\nusing Microsoft.EntityFrameworkCore;\n\nnamespace CurvTabDental.API.Controllers;\n\n// Receptionists see billing amounts and payment records, NOT clinical notes.\n// This is a payment ledger and receipt MVP; invoices, medical-aid claims,\n// refunds, adjustments and debt policies must be added separately.\n[ApiController]\n[Route("api/frontdesk/checkouts")]\n[Authorize(Roles = "Receptionist,PracticeAdmin")]\npublic sealed class ReceptionPaymentsController : ControllerBase\n{\n    private readonly DentalDbContext _db;\n    private readonly ICurrentUser _current;\n    private readonly IAuditService _audit;\n\n    public ReceptionPaymentsController(\n        DentalDbContext db, ICurrentUser current, IAuditService audit)\n    {\n        _db = db;\n        _current = current;\n        _audit = audit;\n    }\n\n    public record RecordPaymentRequest(\n        Guid RequestId, decimal Amount, string Method, string? Reference);\n\n    // GET /api/frontdesk/checkouts/{appointmentId}\n    [HttpGet("{appointmentId:guid}")]\n    public async Task<IActionResult> Details(Guid appointmentId, CancellationToken ct)\n    {\n        if (_current.PracticeId is not Guid practiceId) return Forbid();\n        var details = await LoadDetails(appointmentId, practiceId, ct);\n        return details is null ? NotFound() : Ok(details);\n    }\n\n    // GET /api/frontdesk/checkouts/history?fromUtc=...&toUtc=...\n    [HttpGet("history")]\n    public async Task<IActionResult> History(\n        [FromQuery] DateTimeOffset fromUtc,\n        [FromQuery] DateTimeOffset toUtc,\n        CancellationToken ct)\n    {\n        if (_current.PracticeId is not Guid practiceId) return Forbid();\n        if (fromUtc == default || toUtc <= fromUtc ||\n            toUtc - fromUtc > TimeSpan.FromDays(31))\n            return BadRequest(new { message = "Select a valid date range up to 31 days." });\n\n        var from = fromUtc.UtcDateTime;\n        var to = toUtc.UtcDateTime;\n        var appointments = _db.Appointments.AsNoTracking()\n            .Where(a => a.DentalPracticeId == practiceId &&\n                        a.Status == "CheckedOut" &&\n                        a.CheckedOutAtUtc >= from && a.CheckedOutAtUtc < to)\n            .OrderByDescending(a => a.CheckedOutAtUtc)\n            .Take(200);\n\n        var rows = await (\n            from a in appointments\n            join p in _db.Patients.AsNoTracking() on a.PatientId equals p.Id\n            where p.DentalPracticeId == practiceId\n            select new\n            {\n                appointmentId = a.Id,\n                patientName = p.FirstName + " " + p.LastName,\n                checkedOutAtUtc = a.CheckedOutAtUtc,\n                status = a.Status\n            }).ToListAsync(ct);\n\n        return Ok(rows);\n    }\n\n    // POST /api/frontdesk/checkouts/{appointmentId}/payments\n    // All payment operations for one appointment are serialized with FOR UPDATE.\n    // RequestId is a stable idempotency key, preventing double charges on retries.\n    [HttpPost("{appointmentId:guid}/payments")]\n    public async Task<IActionResult> RecordPayment(\n        Guid appointmentId, [FromBody] RecordPaymentRequest request,\n        CancellationToken ct)\n    {\n        if (_current.PracticeId is not Guid practiceId) return Forbid();\n        if (_current.UserId is not Guid actorId) return Unauthorized();\n\n        if (request.RequestId == Guid.Empty ||\n            request.Amount <= 0m || request.Amount > 10000000m ||\n            decimal.Round(request.Amount, 2) != request.Amount)\n            return BadRequest(new { message = "Supply a valid payment amount and request ID." });\n\n        var method = request.Method?.Trim() ?? "";\n        if (method != "Cash" && method != "Card" && method != "EFT")\n            return BadRequest(new { message = "Payment method must be Cash, Card or EFT." });\n\n        var reference = request.Reference?.Trim();\n        if (reference?.Length > 100 ||\n            ((method == "Card" || method == "EFT") && string.IsNullOrWhiteSpace(reference)))\n            return BadRequest(new\n            {\n                message = "Card and EFT require an external payment reference (never a card number)."\n            });\n\n        await using var transaction = await _db.Database.BeginTransactionAsync(ct);\n\n        // SELECT FOR UPDATE locks this appointment until commit so two cashiers\n        // cannot simultaneously record payments against the same remaining balance.\n        var appointment = await _db.Appointments\n            .FromSqlInterpolated($"SELECT * FROM \\"Appointments\\" WHERE \\"Id\\" = {appointmentId} AND \\"DentalPracticeId\\" = {practiceId} FOR UPDATE")\n            .SingleOrDefaultAsync(ct);\n        if (appointment is null) return NotFound();\n\n        var previous = await _db.Payments.AsNoTracking()\n            .FirstOrDefaultAsync(p => p.DentalPracticeId == practiceId &&\n                                      p.RequestId == request.RequestId, ct);\n        if (previous is not null)\n        {\n            if (previous.AppointmentId != appointmentId ||\n                previous.Amount != request.Amount || previous.Method != method ||\n                previous.Reference != reference)\n                return Conflict(new { message = "This payment request ID was already used." });\n            return Ok(new { paymentId = previous.Id, previous.ReceiptNumber,\n                amount = previous.Amount, alreadyRecorded = true });\n        }\n\n        if (appointment.Status != "AwaitingCheckout")\n            return Conflict(new { message = "This visit is not awaiting checkout." });\n\n        var consultation = await _db.Consultations.AsNoTracking()\n            .FirstOrDefaultAsync(c => c.DentalPracticeId == practiceId &&\n                                      c.AppointmentId == appointmentId && c.IsFinalized, ct);\n        if (consultation is null)\n            return Conflict(new { message = "The Dentist must finish the consultation first." });\n\n        var charged = await _db.ConsultationCharges\n            .Where(c => c.DentalPracticeId == practiceId &&\n                        c.ConsultationId == consultation.Id)\n            .SumAsync(c => (decimal?)c.Amount, ct) ?? 0m;\n        var paid = await _db.Payments\n            .Where(p => p.DentalPracticeId == practiceId &&\n                        p.AppointmentId == appointmentId)\n            .SumAsync(p => (decimal?)p.Amount, ct) ?? 0m;\n        var balance = charged - paid;\n        if (balance <= 0m || request.Amount > balance)\n            return Conflict(new { message = "Payment exceeds the outstanding balance or no amount is due.", balance });\n\n        var paymentId = Guid.NewGuid();\n        var receivedAt = DateTime.UtcNow;\n        var payment = new Payment\n        {\n            Id = paymentId,\n            DentalPracticeId = practiceId,\n            AppointmentId = appointmentId,\n            RequestId = request.RequestId,\n            Amount = request.Amount,\n            Method = method,\n            Reference = reference,\n            ReceivedAtUtc = receivedAt,\n            ReceivedByUserId = actorId,\n            ReceiptNumber = $"RCPT-{receivedAt:yyyyMMdd}-{paymentId.ToString("N")[..12].ToUpperInvariant()}"\n        };\n        _db.Payments.Add(payment);\n        await _db.SaveChangesAsync(ct);\n        await _audit.WriteAsync("PAYMENT_RECORDED", "Payment", payment.Id.ToString(), ct: ct);\n        await transaction.CommitAsync(ct);\n\n        return Created($"/api/frontdesk/payments/{payment.Id}/receipt", new\n        {\n            paymentId = payment.Id,\n            payment.ReceiptNumber,\n            amount = payment.Amount,\n            balance = balance - payment.Amount,\n            alreadyRecorded = false\n        });\n    }\n\n    // POST /api/frontdesk/checkouts/{appointmentId}/complete\n    // Checkout is explicit AFTER receipts are recorded; a R0 visit can\n    // also be checked out. Outstanding balances require an approved debt\n    // workflow which is not enabled in this initial implementation.\n    [HttpPost("{appointmentId:guid}/complete")]\n    public async Task<IActionResult> Complete(Guid appointmentId, CancellationToken ct)\n    {\n        if (_current.PracticeId is not Guid practiceId) return Forbid();\n        await using var transaction = await _db.Database.BeginTransactionAsync(ct);\n        var appointment = await _db.Appointments\n            .FromSqlInterpolated($"SELECT * FROM \\"Appointments\\" WHERE \\"Id\\" = {appointmentId} AND \\"DentalPracticeId\\" = {practiceId} FOR UPDATE")\n            .SingleOrDefaultAsync(ct);\n        if (appointment is null) return NotFound();\n        if (appointment.Status != "AwaitingCheckout")\n            return Conflict(new { message = "Only an awaiting-checkout visit may be checked out." });\n\n        var consultation = await _db.Consultations.AsNoTracking()\n            .FirstOrDefaultAsync(c => c.DentalPracticeId == practiceId &&\n                                      c.AppointmentId == appointmentId && c.IsFinalized, ct);\n        if (consultation is null)\n            return Conflict(new { message = "The Dentist has not finalized this consultation." });\n\n        var charged = await _db.ConsultationCharges\n            .Where(c => c.DentalPracticeId == practiceId &&\n                        c.ConsultationId == consultation.Id)\n            .SumAsync(c => (decimal?)c.Amount, ct) ?? 0m;\n        var paid = await _db.Payments\n            .Where(p => p.DentalPracticeId == practiceId &&\n                        p.AppointmentId == appointmentId)\n            .SumAsync(p => (decimal?)p.Amount, ct) ?? 0m;\n        if (charged != paid)\n            return Conflict(new\n            {\n                message = "Outstanding balance must be zero to complete checkout.",\n                balance = charged - paid\n            });\n\n        appointment.Status = "CheckedOut";\n        appointment.CheckedOutAtUtc = DateTime.UtcNow;\n        await _db.SaveChangesAsync(ct);\n        await _audit.WriteAsync("PATIENT_CHECKED_OUT", "Appointment", appointmentId.ToString(), ct: ct);\n        await transaction.CommitAsync(ct);\n        return Ok(new { appointmentId, status = "CheckedOut", appointment.CheckedOutAtUtc });\n    }\n\n    // GET /api/frontdesk/payments/{paymentId}/receipt\n    [HttpGet("/api/frontdesk/payments/{paymentId:guid}/receipt")]\n    public async Task<IActionResult> Receipt(Guid paymentId, CancellationToken ct)\n    {\n        if (_current.PracticeId is not Guid practiceId) return Forbid();\n        var payment = await _db.Payments.AsNoTracking()\n            .FirstOrDefaultAsync(p => p.Id == paymentId && p.DentalPracticeId == practiceId, ct);\n        if (payment is null) return NotFound();\n        var details = await LoadDetails(payment.AppointmentId, practiceId, ct);\n        if (details is null) return NotFound();\n        var practiceName = await _db.DentalPractices.AsNoTracking()\n            .Where(p => p.Id == practiceId)\n            .Select(p => p.Name)\n            .FirstOrDefaultAsync(ct);\n        // The receipt reflects the balance immediately after THIS payment,\n        // not a later balance after other payments have been received.\n        var previouslyPaid = details.Payments\n            .TakeWhile(p => p.Id != payment.Id)\n            .Sum(p => p.Amount);\n        var paidAtReceipt = previouslyPaid + payment.Amount;\n\n        return Ok(new\n        {\n            payment.ReceiptNumber,\n            paymentId = payment.Id,\n            payment.AppointmentId,\n            practiceName = practiceName ?? "Dental Practice",\n            details.PatientName,\n            payment.Amount,\n            payment.Method,\n            payment.Reference,\n            payment.ReceivedAtUtc,\n            currency = "ZAR",\n            amountBilled = details.AmountDue,\n            totalPaid = paidAtReceipt,\n            balance = details.AmountDue - paidAtReceipt,\n            details.Status\n        });\n    }\n\n    private sealed record PaymentRow(Guid Id, string ReceiptNumber,\n        decimal Amount, string Method, string? Reference, DateTime ReceivedAtUtc);\n    private sealed record CheckoutDetails(\n        Guid AppointmentId, Guid PatientId, string PatientName, string Status,\n        DateTime? CompletedAtUtc, DateTime? CheckedOutAtUtc,\n        decimal AmountDue, decimal AmountPaid, decimal Balance,\n        string Currency, List<PaymentRow> Payments);\n\n    private async Task<CheckoutDetails?> LoadDetails(\n        Guid appointmentId, Guid practiceId, CancellationToken ct)\n    {\n        var appointment = await _db.Appointments.AsNoTracking()\n            .FirstOrDefaultAsync(a => a.Id == appointmentId &&\n                                      a.DentalPracticeId == practiceId &&\n                                      (a.Status == "AwaitingCheckout" || a.Status == "CheckedOut"), ct);\n        if (appointment is null) return null;\n        var patient = await _db.Patients.AsNoTracking()\n            .FirstOrDefaultAsync(p => p.Id == appointment.PatientId &&\n                                      p.DentalPracticeId == practiceId, ct);\n        if (patient is null) return null;\n        var consultation = await _db.Consultations.AsNoTracking()\n            .FirstOrDefaultAsync(c => c.DentalPracticeId == practiceId &&\n                                      c.AppointmentId == appointmentId && c.IsFinalized, ct);\n        if (consultation is null) return null;\n\n        var due = await _db.ConsultationCharges\n            .Where(c => c.DentalPracticeId == practiceId && c.ConsultationId == consultation.Id)\n            .SumAsync(c => (decimal?)c.Amount, ct) ?? 0m;\n        var payments = await _db.Payments.AsNoTracking()\n            .Where(p => p.DentalPracticeId == practiceId && p.AppointmentId == appointmentId)\n            .OrderBy(p => p.ReceivedAtUtc)\n            .ThenBy(p => p.Id)\n            .Select(p => new PaymentRow(p.Id, p.ReceiptNumber, p.Amount,\n                p.Method, p.Reference, p.ReceivedAtUtc))\n            .ToListAsync(ct);\n        var paid = payments.Sum(p => p.Amount);\n        return new CheckoutDetails(appointment.Id, patient.Id,\n            patient.FirstName + " " + patient.LastName, appointment.Status,\n            appointment.ConsultationEndedAtUtc, appointment.CheckedOutAtUtc,\n            due, paid, due - paid, "ZAR", payments);\n    }\n}\n'

FILE_FRONTEND = 'import { useEffect, useRef, useState } from \'react\'\nimport type { FormEvent } from \'react\'\nimport { CheckCircle2, CreditCard, FileText, Printer, RefreshCw, Wallet } from \'lucide-react\'\nimport { apiRequest } from \'../services/api\'\nimport \'./ReceptionCheckoutPage.css\'\n\ntype WaitingCheckout = {\n  appointmentId: string\n  patientId: string\n  patientName: string\n  status: string\n  completedAtUtc: string | null\n  amountDue: number\n  currency: string\n}\ntype HistoryRow = {\n  appointmentId: string\n  patientName: string\n  checkedOutAtUtc: string | null\n  status: string\n}\ntype Payment = {\n  id: string\n  receiptNumber: string\n  amount: number\n  method: string\n  reference: string | null\n  receivedAtUtc: string\n}\ntype Details = {\n  appointmentId: string\n  patientId: string\n  patientName: string\n  status: string\n  completedAtUtc: string | null\n  checkedOutAtUtc: string | null\n  amountDue: number\n  amountPaid: number\n  balance: number\n  currency: string\n  payments: Payment[]\n}\ntype PaymentResult = {\n  paymentId: string\n  receiptNumber: string\n  amount: number\n  balance?: number\n  alreadyRecorded: boolean\n}\ntype Receipt = {\n  receiptNumber: string\n  paymentId: string\n  appointmentId: string\n  practiceName: string\n  patientName: string\n  amount: number\n  method: string\n  reference: string | null\n  receivedAtUtc: string\n  currency: string\n  amountBilled: number\n  totalPaid: number\n  balance: number\n  status: string\n}\n\nfunction money(value: number) {\n  return new Intl.NumberFormat(\'en-ZA\', { style: \'currency\', currency: \'ZAR\' }).format(value)\n}\nfunction when(value: string | null) {\n  return value ? new Date(value).toLocaleString(\'en-ZA\', {\n    dateStyle: \'medium\', timeStyle: \'short\',\n  }) : \'—\'\n}\nfunction errorMessage(cause: unknown) {\n  return cause instanceof Error ? cause.message : \'Unable to complete request.\'\n}\nfunction todayRange() {\n  const now = new Date()\n  const start = new Date(now.getFullYear(), now.getMonth(), now.getDate())\n  const end = new Date(start)\n  end.setDate(end.getDate() + 1)\n  return `fromUtc=${encodeURIComponent(start.toISOString())}&toUtc=${encodeURIComponent(end.toISOString())}`\n}\n\nexport default function ReceptionCheckoutPage() {\n  const [tab, setTab] = useState<\'ready\' | \'completed\'>(\'ready\')\n  const [ready, setReady] = useState<WaitingCheckout[]>([])\n  const [completed, setCompleted] = useState<HistoryRow[]>([])\n  const [selectedId, setSelectedId] = useState<string | null>(null)\n  const [detail, setDetail] = useState<Details | null>(null)\n  const [receipt, setReceipt] = useState<Receipt | null>(null)\n  const [method, setMethod] = useState<\'Cash\' | \'Card\' | \'EFT\'>(\'Cash\')\n  const [amount, setAmount] = useState(\'\')\n  const [reference, setReference] = useState(\'\')\n  const [busy, setBusy] = useState(false)\n  const [loading, setLoading] = useState(true)\n  const [error, setError] = useState(\'\')\n  const [success, setSuccess] = useState(\'\')\n  const [revision, setRevision] = useState(0)\n  const paymentRequestId = useRef<string | null>(null)\n\n  useEffect(() => {\n    let active = true\n    Promise.all([\n      apiRequest<WaitingCheckout[]>(\'/frontdesk/checkout-ready\'),\n      apiRequest<HistoryRow[]>(`/frontdesk/checkouts/history?${todayRange()}`),\n    ]).then(([waiting, history]) => {\n      if (!active) return\n      setReady(waiting)\n      setCompleted(history)\n      setError(\'\')\n    }).catch(cause => { if (active) setError(errorMessage(cause)) })\n      .finally(() => { if (active) setLoading(false) })\n    return () => { active = false }\n  }, [revision])\n\n  useEffect(() => {\n    if (!selectedId) return\n    let active = true\n    apiRequest<Details>(`/frontdesk/checkouts/${encodeURIComponent(selectedId)}`)\n      .then(result => {\n        if (!active) return\n        setDetail(result)\n        setAmount(result.balance > 0 ? result.balance.toFixed(2) : \'\')\n      })\n      .catch(cause => { if (active) setError(errorMessage(cause)) })\n    return () => { active = false }\n  }, [selectedId, revision])\n\n  function refresh() {\n    setLoading(true)\n    setRevision(value => value + 1)\n  }\n\n  function choose(id: string) {\n    setSelectedId(id)\n    setDetail(null)\n    setReceipt(null)\n    setError(\'\')\n    setSuccess(\'\')\n    setReference(\'\')\n    setMethod(\'Cash\')\n    paymentRequestId.current = null\n  }\n\n  async function showReceipt(paymentId: string) {\n    setError(\'\')\n    try {\n      const value = await apiRequest<Receipt>(\n        `/frontdesk/payments/${encodeURIComponent(paymentId)}/receipt`\n      )\n      setReceipt(value)\n    } catch (cause) {\n      setError(errorMessage(cause))\n    }\n  }\n\n  async function recordPayment(event: FormEvent<HTMLFormElement>) {\n    event.preventDefault()\n    if (!detail || busy || detail.status !== \'AwaitingCheckout\') return\n    const received = Number(amount)\n    if (!Number.isFinite(received) || received <= 0 || received > detail.balance ||\n        Math.abs(Math.round(received * 100) - received * 100) > 0.000001) {\n      setError(\'Enter a valid amount that does not exceed the outstanding balance.\')\n      return\n    }\n    if (method !== \'Cash\' && !reference.trim()) {\n      setError(\'Enter the card terminal or EFT reference (not the card number).\')\n      return\n    }\n    setBusy(true)\n    setError(\'\')\n    setSuccess(\'\')\n    try {\n      if (!paymentRequestId.current) paymentRequestId.current = crypto.randomUUID()\n      const result = await apiRequest<PaymentResult>(\n        `/frontdesk/checkouts/${encodeURIComponent(detail.appointmentId)}/payments`,\n        \'POST\',\n        { requestId: paymentRequestId.current, amount: received, method,\n          reference: reference.trim() || null }\n      )\n      paymentRequestId.current = null\n      setSuccess(result.alreadyRecorded\n        ? \'This payment was already recorded; no duplicate was created.\'\n        : \'Payment recorded successfully. Receipt is ready.\')\n      setReference(\'\')\n      setMethod(\'Cash\')\n      await showReceipt(result.paymentId)\n      refresh()\n    } catch (cause) {\n      // Keep the request ID on errors so retries do not create duplicates.\n      setError(errorMessage(cause))\n    } finally {\n      setBusy(false)\n    }\n  }\n\n  async function finishCheckout() {\n    if (!detail || busy || detail.balance !== 0 || detail.status !== \'AwaitingCheckout\') return\n    setBusy(true)\n    setError(\'\')\n    setSuccess(\'\')\n    try {\n      await apiRequest(`/frontdesk/checkouts/${encodeURIComponent(detail.appointmentId)}/complete`, \'POST\')\n      setSuccess(\'Patient checked out. The visit remains in Completed Today.\')\n      refresh()\n    } catch (cause) {\n      setError(errorMessage(cause))\n    } finally {\n      setBusy(false)\n    }\n  }\n\n  return (\n    <div className="checkout-page">\n      <div className="page-heading">\n        <div><div className="eyebrow">FRONT DESK</div><h1>Checkout &amp; Payments</h1>\n          <p>Receive confirmed charges from the Dentist, record payments and print receipts.</p></div>\n        <button type="button" className="secondary-button" onClick={refresh} disabled={busy || loading}>\n          <RefreshCw size={17} /> Refresh\n        </button>\n      </div>\n      <div className="checkout-tabs">\n        <button type="button" className={tab === \'ready\' ? \'primary-button\' : \'secondary-button\'}\n          onClick={() => setTab(\'ready\')}>Awaiting Checkout ({ready.length})</button>\n        <button type="button" className={tab === \'completed\' ? \'primary-button\' : \'secondary-button\'}\n          onClick={() => setTab(\'completed\')}>Completed Today ({completed.length})</button>\n      </div>\n      {error && <p role="alert" className="checkout-alert checkout-error">{error}</p>}\n      {success && <p role="status" className="checkout-alert checkout-success"><CheckCircle2 size={16}/>{success}</p>}\n      <div className="checkout-grid">\n        <section className="panel checkout-list">\n          <div className="panel-header"><div><h2>{tab === \'ready\' ? \'Ready for Checkout\' : \'Completed Today\'}</h2>\n            <p>{tab === \'ready\' ? \'Completed consultations sent by the Dentist\' : \'Visits checked out today\'}</p>\n          </div><Wallet size={20}/></div>\n          {loading ? <p>Loading checkout records...</p> : tab === \'ready\' ? (\n            ready.length === 0 ? <p className="checkout-empty">No patients awaiting checkout.</p> : (\n              ready.map(row => <button type="button" key={row.appointmentId}\n                className={`checkout-patient ${selectedId === row.appointmentId ? \'checkout-selected\' : \'\'}`}\n                onClick={() => choose(row.appointmentId)}>\n                <strong>{row.patientName}</strong>\n                <small>Consultation completed {when(row.completedAtUtc)}</small>\n                <span>{money(row.amountDue)} billed</span>\n              </button>)\n            )\n          ) : completed.length === 0 ? (\n            <p className="checkout-empty">No patients checked out today.</p>\n          ) : completed.map(row => <button type="button" key={row.appointmentId}\n            className={`checkout-patient ${selectedId === row.appointmentId ? \'checkout-selected\' : \'\'}`}\n            onClick={() => choose(row.appointmentId)}>\n            <strong>{row.patientName}</strong>\n            <small>Checked out {when(row.checkedOutAtUtc)}</small>\n            <span>Checked Out</span>\n          </button>)}\n        </section>\n        <section className="panel checkout-detail">\n          {!selectedId ? (\n            <div className="checkout-empty"><CreditCard size={27}/><h2>Select a patient</h2>\n              <p>Choose a completed consultation to view the amount due and record payment.</p></div>\n          ) : !detail || detail.appointmentId !== selectedId ? <p>Loading payment details...</p> : (\n            <>\n              <div className="panel-header"><div><h2>{detail.patientName}</h2>\n                <p>Consultation finished: {when(detail.completedAtUtc)}</p></div>\n                <span className="checkout-status">{detail.status}</span>\n              </div>\n              <div className="checkout-amounts">\n                <div><span>Amount charged by Dentist</span><strong>{money(detail.amountDue)}</strong></div>\n                <div><span>Payments received</span><strong>{money(detail.amountPaid)}</strong></div>\n                <div className="checkout-due"><span>Remaining balance</span><strong>{money(detail.balance)}</strong></div>\n              </div>\n              {detail.status === \'AwaitingCheckout\' && detail.balance > 0 && (\n                <form className="checkout-payment-form" onSubmit={recordPayment}>\n                  <h3>Record payment received</h3>\n                  <label>Payment method\n                    <select value={method} onChange={event => {\n                      setMethod(event.target.value as \'Cash\' | \'Card\' | \'EFT\')\n                      paymentRequestId.current = null\n                    }} disabled={busy}>\n                      <option value="Cash">Cash</option><option value="Card">Card terminal</option><option value="EFT">EFT</option>\n                    </select>\n                  </label>\n                  <label>Amount received (ZAR)\n                    <input type="number" min="0.01" step="0.01" max={detail.balance}\n                      value={amount} disabled={busy} required\n                      onChange={event => { setAmount(event.target.value); paymentRequestId.current = null }} />\n                  </label>\n                  <label>External payment reference {method !== \'Cash\' ? \'(required)\' : \'(optional)\'}\n                    <input type="text" maxLength={100} value={reference} disabled={busy}\n                      placeholder={method === \'Cash\' ? \'Optional cash reference\' : \'Terminal/EFT transaction reference — no card numbers\'}\n                      onChange={event => { setReference(event.target.value); paymentRequestId.current = null }} />\n                  </label>\n                  <button type="submit" className="primary-button" disabled={busy}>\n                    <Wallet size={17}/>{busy ? \'Recording...\' : \'Record Payment & Generate Receipt\'}\n                  </button>\n                  <p className="checkout-hint">Partial payments are supported. Checkout is enabled only when the remaining balance is zero.</p>\n                </form>\n              )}\n              {detail.status === \'AwaitingCheckout\' && detail.balance === 0 && (\n                <div className="checkout-payment-form">\n                  <p className="checkout-success">Balance is zero. You may complete checkout.</p>\n                  <button type="button" className="primary-button" disabled={busy} onClick={() => void finishCheckout()}>\n                    <CheckCircle2 size={17}/> Complete Checkout\n                  </button>\n                </div>\n              )}\n              {detail.status === \'CheckedOut\' && <p className="checkout-alert checkout-success">\n                <CheckCircle2 size={17}/> Checked out: {when(detail.checkedOutAtUtc)}</p>}\n              <div className="checkout-received">\n                <h3>Payment history & receipts</h3>\n                {detail.payments.length === 0 ? <p>No payments recorded for this visit.</p>\n                  : detail.payments.map(item => <div className="checkout-payment-row" key={item.id}>\n                    <div><strong>{money(item.amount)} · {item.method}</strong>\n                      <small>{when(item.receivedAtUtc)} · {item.receiptNumber}</small></div>\n                    <button className="secondary-button" type="button" onClick={() => void showReceipt(item.id)}>\n                      <FileText size={16}/> Receipt\n                    </button>\n                  </div>)}\n              </div>\n            </>\n          )}\n        </section>\n      </div>\n      {receipt && <section className="panel checkout-print-panel">\n        <div className="checkout-print-actions">\n          <h2>Payment Receipt</h2>\n          <button type="button" className="secondary-button" onClick={() => window.print()}>\n            <Printer size={17}/> Print Receipt\n          </button>\n        </div>\n        <div className="checkout-receipt-print">\n          <h2>{receipt.practiceName}</h2>\n          <h3>PAYMENT RECEIPT</h3>\n          <p><strong>Receipt:</strong> {receipt.receiptNumber}</p>\n          <p><strong>Date:</strong> {when(receipt.receivedAtUtc)}</p>\n          <p><strong>Patient:</strong> {receipt.patientName}</p>\n          <p><strong>Service:</strong> Dental services</p>\n          <p><strong>Method:</strong> {receipt.method}</p>\n          {receipt.reference && <p><strong>Transaction reference:</strong> {receipt.reference}</p>}\n          <hr/>\n          <p><strong>Amount received:</strong> {money(receipt.amount)}</p>\n          <p><strong>Total billed for visit:</strong> {money(receipt.amountBilled)}</p>\n          <p><strong>Total received for visit:</strong> {money(receipt.totalPaid)}</p>\n          <p><strong>Outstanding balance:</strong> {money(receipt.balance)}</p>\n          <p className="checkout-receipt-note">Payment acknowledgement only. Not a tax invoice or medical-aid claim.</p>\n        </div>\n      </section>}\n    </div>\n  )\n}\n'

